// An image source. read(x, y, width, height, step) decodes the full-resolution window and keeps every step-th pixel.
export function sourceOf(decoder, width, height) {
  return {
    width,
    height,
    read: (x, y, w, h, step) => decoder.window(x, y, w, h, step),
  };
}

