// Streamed COG writer: full resolution, then each overview level.
export async function writeCog(source, sink, levels) {
  await writeLevel(sink, 0, source.width, source.height, (y, rows) => source.read(0, y, source.width, rows, 1));
  for (let level = 1; level <= levels; level += 1) {
    const step = 2 ** level;
    const width = Math.ceil(source.width / step);
    const height = Math.ceil(source.height / step);
    await writeLevel(sink, level, width, height, (y, rows) =>
      source.read(0, y * step, source.width, rows * step, step));
  }
}

async function writeLevel(sink, level, width, height, read) {
  for (let y = 0; y < height; y += 256) {
    const rows = Math.min(256, height - y);
    sink.write(level, y, await read(y, rows));
  }
}
